extra_head_css:
.merger-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .merger-sidebar { flex: 0 0 280px; display: flex; flex-direction: column; gap: 16px; }
    .merger-canvas-area { flex: 1; min-width: 300px; }

    .image-list { display: flex; flex-direction: column; gap: 8px; max-height: 360px; overflow-y: auto; padding: 4px; }
    .image-list-item {
      display: flex; align-items: center; gap: 10px; padding: 8px 10px;
      background: var(--bg-secondary); border: 1px solid var(--border); border-radius: 8px;
      cursor: grab; transition: box-shadow .2s, transform .15s;
    }
    .image-list-item:hover { box-shadow: 0 2px 8px rgba(0,0,0,.2); }
    .image-list-item.dragging { opacity: 0.5; transform: scale(0.96); }
    .image-list-item.drag-over { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent); }
    .image-list-item img { width: 48px; height: 48px; object-fit: cover; border-radius: 4px; flex-shrink: 0; }
    .image-list-item .item-info { flex: 1; min-width: 0; }
    .image-list-item .item-name { font-size: .8rem; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .image-list-item .item-size { font-size: .7rem; color: var(--text-secondary); }
    .image-list-item .item-remove {
      background: none; border: none; color: var(--text-secondary); cursor: pointer;
      font-size: 1.1rem; padding: 4px; line-height: 1; border-radius: 4px; transition: background .2s;
    }
    .image-list-item .item-remove:hover { background: rgba(255,60,60,.2); color: #ff3c3c; }

    .control-group { display: flex; flex-direction: column; gap: 6px; }
    .control-group label { font-size: .8rem; color: var(--text-secondary); font-weight: 500; }
    .control-group select, .control-group input[type="number"] {
      padding: 8px 10px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .85rem;
    }
    .control-group input[type="color"] {
      width: 100%; height: 36px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); cursor: pointer; padding: 2px;
    }
    .control-group input[type="range"] { width: 100%; }

    .layout-btns { display: flex; gap: 6px; }
    .layout-btn {
      flex: 1; padding: 8px 4px; border: 2px solid var(--border); border-radius: 8px;
      background: var(--bg-primary); color: var(--text-secondary); cursor: pointer;
      text-align: center; font-size: .75rem; transition: all .2s; display: flex;
      flex-direction: column; align-items: center; gap: 4px;
    }
    .layout-btn:hover { border-color: var(--accent); color: var(--text-primary); }
    .layout-btn.active { border-color: var(--accent); background: rgba(99,102,241,.1); color: var(--accent); }
    .layout-btn .layout-icon { font-size: 1.3rem; }

    .canvas-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border: 1px solid var(--border); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 300px;
      overflow: auto;
    }
    .canvas-wrapper canvas { max-width: 100%; max-height: 500px; border-radius: 4px; }

    .add-more-btn {
      display: flex; align-items: center; justify-content: center; gap: 6px;
      padding: 10px; border: 2px dashed var(--border); border-radius: 8px;
      background: none; color: var(--text-secondary); cursor: pointer;
      font-size: .85rem; transition: all .2s; width: 100%;
    }
    .add-more-btn:hover { border-color: var(--accent); color: var(--accent); }

    @media (max-width: 768px) {
      .merger-workspace { flex-direction: column; }
      .merger-sidebar { flex: none; width: 100%; }
    }
